theorem exposition_forrelation_matrix :
  let H : Matrix (Fin 4) (Fin 4) ℚ :=
    !![1/2, 1/2, 1/2, 1/2;
       1/2, -1/2, 1/2, -1/2;
       1/2, 1/2, -1/2, -1/2;
       1/2, -1/2, -1/2, 1/2]
  let v : Fin 4 → ℚ := ![1, 1, 1, -1]
  let w : Fin 4 → ℚ := ![1, 1, -1, 1]
  H * H.transpose = 1 ∧
    H.mulVec v = v ∧
    (∑ i : Fin 4, v i * H.mulVec v i) = 4 ∧
    (∑ i : Fin 4, w i * H.mulVec v i) = 0 ∧
    (∑ i : Fin 4, (-v i) * H.mulVec v i) = -4
